<?php require_once __DIR__ . '/../includes/helpers.php'; require_login(); verify_csrf(); $err=''; if($_SERVER['REQUEST_METHOD']==='POST'){ $p=$_POST['password']??''; $c=$_POST['confirm_password']??''; if($p!==$c)$err='Passwords do not match.'; elseif($e=password_policy_error($p))$err=$e; else { $h=password_hash($p,PASSWORD_BCRYPT); $id=current_user()['id']; $stmt=db()->prepare('UPDATE users SET password_hash=?, must_change_password=0 WHERE id=?'); $stmt->bind_param('si',$h,$id); $stmt->execute(); audit('password_changed','user',$id); redirect(dashboard_for(current_user()['role'])); }} ?><!DOCTYPE html><html><head><meta name="viewport" content="width=device-width, initial-scale=1"><title>Change Password</title><link rel="stylesheet" href="<?= BASE_URL ?>/assets/css/style.css"></head><body class="auth-body"><section class="auth-card"><h1>Change Password</h1><?php if($err): ?><div class="alert alert-danger"><?= e($err) ?></div><?php endif; ?><form method="post"><?= csrf_field() ?><label>New password<input type="password" name="password" required></label><label>Confirm password<input type="password" name="confirm_password" required></label><button class="btn btn-primary full">Continue</button></form></section></body></html>
